const slug = (text: string) => text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
  .replace(/\([^)]*\)/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

/** The rows as the bank tables take them, in each country's own money. */
export function worldBanking(currencyOf: (iso: string) => string): CountryBanking[] {
  return ROWS.filter((row) => row.banks.length > 0).map((row) => {
    const currency = currencyOf(row.iso);
    return {
      iso: row.iso,
      guarantee: row.guarantee && {
        scheme: row.guarantee.scheme, limit: row.guarantee.limit, currency: row.guarantee.currency,
        note: row.guarantee.note, source: row.guarantee.source,
      },
      banks: row.banks.map((name) => ({
        id: `${row.iso.toLowerCase()}-${slug(name)}`,
        name,
        iso: row.iso,
        currency,
        format: row.format,
        code: '',
        ibanCountry: row.ibanCountry,
        ibanLength: row.ibanLength,
        current: { name: row.checking ? 'Checking Account' : 'Current Account', source: `no product sheet on record; the bank from ${row.source}`, asOf: '2026-09-25' },
        savings: { name: 'Savings Account', source: `no product sheet on record; the bank from ${row.source}`, asOf: '2026-09-25' },
        confidence: row.confidence,
      })),
    };
  });
}
